/* El disco de Render se limpia al desplegar: esto permite guardarlo y recuperarlo */
/* Une dos Trofeos: suma las fichas de cada uno y junta las partidas */
function unirPalmares(base, otro){
  const r = { partidas: (base.partidas || []).slice(), gente: {} };
  Object.keys(base.gente || {}).forEach(n => {
    const g = base.gente[n];
    r.gente[n] = { jugadas:g.jugadas||0, ganadas:g.ganadas||0,
                   puntos:g.puntos||0, reyes:g.reyes||0, medallas:g.medallas||0 };
  });
  Object.keys(otro.gente || {}).forEach(n => {
    const g = otro.gente[n];
    if (!r.gente[n]) r.gente[n] = { jugadas:0, ganadas:0, puntos:0, reyes:0, medallas:0 };
    r.gente[n].jugadas  += g.jugadas  || 0;
    r.gente[n].ganadas  += g.ganadas  || 0;
    r.gente[n].puntos   += g.puntos   || 0;
    r.gente[n].reyes    += g.reyes    || 0;
    r.gente[n].medallas += g.medallas || 0;
  });
  const vistas = {};
  r.partidas = r.partidas.concat(otro.partidas || []).filter(p => {
    const k = (p.fecha || 0) + '|' + (p.ganador || '');
    if (vistas[k]) return false;
    vistas[k] = true; return true;
  }).sort((a,b) => (b.fecha||0) - (a.fecha||0)).slice(0, 40);
  return r;
}

app.get('/palmares/copia', (_req, res) => {
  res.setHeader('Content-Disposition', 'attachment; filename="trofeo-king.json"');
  res.json(leerPalmares());
});
app.post('/palmares/restaurar', express.json({ limit: '2mb' }), (req, res) => {
  try {
    const d = req.body;
    if (!d || typeof d !== 'object' || !d.gente) return res.status(400).json({ error: 'formato' });
    // Con ?unir=1 se suma al Trofeo que ya hay, en vez de pisarlo
    const final = (req.query.unir === '1') ? unirPalmares(leerPalmares(), d) : d;
    fs.writeFileSync(PALMARES, JSON.stringify(final));
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: 'no se pudo' }); }
});
app.get('/cara.png', (_req, res) => {
  res.type('jpeg').set('Cache-Control', 'public, max-age=604800').send(CARA);
});


/* ═════ SOCIOS ═════
   Entrada con el celular: se pide un código, llega por WhatsApp y abre
   sesión. Sin WhatsApp configurado, el código sale en el registro. */
app.post('/socio/codigo', express.json(), async (req, res) => {
  const r = await socios.pedirCodigo((req.body || {}).telefono);
  if (!r.ok) return res.status(400).json(r);
  res.json({ ok: true, telefono: r.telefono });      // el código NO se devuelve
});

app.post('/socio/entrar', express.json(), async (req, res) => {
  const b = req.body || {};
  const r = await socios.usarCodigo(b.telefono, b.codigo);
  if (!r.ok) return res.status(400).json(r);
  res.json({ ok: true, sesion: r.sesion });
});

app.get('/socio/quien', async (req, res) => {
  res.json(socios.situacion(await socios.quienEs(req.query.s || '')));
});

/* Activación a mano mientras no esté la pasarela. Con dinero de verdad
   la llamará la pasarela al confirmar el cobro, no una persona. */
app.post('/socio/activar', express.json(), async (req, res) => {
  const b = req.body || {};
  if (!process.env.KING_LLAVE || b.llave !== process.env.KING_LLAVE)
    return res.status(403).json({ error: 'no autorizado' });
  const cuenta = await socios.activar(b.telefono, b.meses || 1);
  if (!cuenta) return res.status(400).json({ error: 'número no válido' });
  res.json({ ok: true, telefono: cuenta.telefono, hasta: cuenta.hasta });
});


