function llaveBuena(llave){
  return !!process.env.KING_LLAVE && llave === process.env.KING_LLAVE;
}

app.get('/socio/panel', (req, res) => {
  if (!process.env.KING_LLAVE) return res.status(503).send('Falta configurar KING_LLAVE en Render');
  if (!llaveBuena(req.query.llave)) return res.status(403).send('No autorizado');
  res.send(paginaPanel(req.query.llave));
});

app.post('/socio/panel', express.urlencoded({ extended: false }), async (req, res) => {
  const b = req.body || {};
  if (!llaveBuena(b.llave)) return res.status(403).send('No autorizado');
  const cuenta = await socios.activar(b.telefono, parseInt(b.meses, 10) || 1);
  let aviso;
  if (!cuenta) aviso = '<div class="mal">Ese número no es un celular colombiano válido</div>';
  else {
    const d = new Date(cuenta.hasta);
    aviso = '<div class="ok">Activada: ' + cuenta.telefono + ' hasta el ' +
            d.getDate() + '/' + (d.getMonth() + 1) + '/' + d.getFullYear() + '</div>';
  }
  res.send(paginaPanel(b.llave, aviso));
});

