const RONDAS_PARTIDA = 4;   // una partida son cuatro rondas
const CODIGO_HABITUAL = 'CUCA';

/* Los ocho colores que puede elegir un jugador. Si dos piden el mismo,
   el segundo se queda con el primero libre: en la mesa nunca se repiten. */
const PALETA_JUGADOR = ['#39b6f0','#e07a1f','#8b5cf6','#2ed06e',
                        '#e0453c','#f2c14e','#16a3a3','#e86ba8'];

function colorLibre(sala, pedido){
  const usados = sala.jugadores.map(j => j.color).filter(Boolean);
  if (pedido && PALETA_JUGADOR.indexOf(pedido) >= 0 && usados.indexOf(pedido) < 0) return pedido;
  return PALETA_JUGADOR.find(c => usados.indexOf(c) < 0) || PALETA_JUGADOR[0];
}

/* Sentarse a una mesa pide membresía al día: cada jugador la suya.
   Los bots no pagan, porque no ocupan cuenta. */
async function dejaPasar(ws, m){
  const cuenta = await socios.quienEs(m.sesion || '');
  if (!cuenta){
    enviar(ws, 'error', { texto: 'Entra con tu celular para poder jugar', socio: 'sin-sesion' });
    return null;
  }
  if (!socios.alDia(cuenta)){
    enviar(ws, 'error', { texto: 'Tu membresía venció. Renuévala para volver a la mesa',
                          socio: 'vencida', telefono: cuenta.telefono });
    return null;
  }
  return cuenta;
}

function codigoNuevo() {
  // La mesa de siempre, si está libre
  if (!salas.has(CODIGO_HABITUAL)) return CODIGO_HABITUAL;
  // Si ya hay una en marcha, la siguiente lleva código al azar
  const letras = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let cod;
  do {
    cod = Array.from({ length: 4 }, () => letras[Math.floor(Math.random() * letras.length)]).join('');
  } while (salas.has(cod));
  return cod;
}

function crearSala(codigo) {
  return {
    codigo,
    jugadores: [],        // { id, nombre, ws, conectado }
    empezada: false,
    parejas: false,   // Norte con Sur contra Oeste con Este
    manos: [[],[],[],[]],
    marcador: [0,0,0,0],
    puntosMano: [0,0,0,0],
    iMano: 0,
    ronda: 1,
    abreBase: 3,   // la ronda arranca abriendo el del este
    triunfo: null,
    mesa: [],
    turno: 0,
    nBaza: 1,
    esperandoTriunfo: null,   // índice del jugador que debe elegir palo
    ultimaBaza: null,
    salidas: {},          // cartas ya vistas en la mano
    fallos: [{},{},{},{}], // a quién le falta cada palo
    resolviendo: false,
    terminada: false,
    rondas: [],  // posicion y puntos de cada ronda cerrada
    medallas: [0,0,0,0]   // rondas ganadas dentro de esta partida
  };
}

function quienAbre(sala) {
  let abre = ((sala.abreBase + sala.iMano) % 4 + 4) % 4;
  const mano = MANOS[sala.iMano];
  // En una mano de triunfo, si le tocara abrir a su propio dueño,
  // sale el jugador de su izquierda.
  if (mano.tipo === 'pos' && abre === mano.dueno) abre = (abre + 1) % 4;
  return abre;
}

/* ─────────── ENVÍO DE ESTADO ─────────── */
function enviar(ws, tipo, datos) {
  if (ws && ws.readyState === 1) ws.send(JSON.stringify({ tipo, ...datos }));
}

function difundir(sala, tipo, datos) {
  sala.jugadores.forEach(j => enviar(j.ws, tipo, datos));
}

// Cada jugador recibe solo su mano; de los demás, cuántas cartas les quedan
/* Si quien manda deja la mesa, el mando pasa al siguiente que siga conectado.
   Si no, nadie podría sacar a nadie ni pedir revancha. */
function pasarElMando(sala) {
  const cero = sala.jugadores[0];
  if (cero && cero.ws && !cero.vacante) return;   // sigue estando
  const nuevo = sala.jugadores.findIndex(j => j && j.ws && !j.vacante);
  if (nuevo <= 0) return;
  const tmp = sala.jugadores[0];
  sala.jugadores[0] = sala.jugadores[nuevo];
  sala.jugadores[nuevo] = tmp;
  // Las manos y los puntos van con el asiento, así que se cambian también
  [ 'manos', 'marcador', 'puntosMano', 'reyesCargados', 'fallos' ].forEach(k => {
    if (!Array.isArray(sala[k])) return;
    const t = sala[k][0]; sala[k][0] = sala[k][nuevo]; sala[k][nuevo] = t;
  });
  sala.jugadores.forEach((j, i) => { if (j && j.ws) enviar(j.ws, 'sala', { codigo: sala.codigo, yo: i }); });
}

function estadoPara(sala, idx) {
  const mano = MANOS[sala.iMano];
  const salida = sala.mesa.length ? sala.mesa[0].carta.p : null;
  const miTurno = sala.empezada && sala.turno === idx &&
                  !sala.esperandoTriunfo && !sala.resolviendo;
  return {
    codigo: sala.codigo,
    empezada: sala.empezada,
    yo: idx,
    jugadores: sala.jugadores.map(j => ({ nombre: j.nombre, conectado: j.conectado,
                                          vacante: !!j.vacante, pausa: !!j.pausa, bot: !!j.bot,
                                          color: j.color || null })),
    misCartas: sala.manos[idx] || [],
    jugables: miTurno ? jugables(sala.manos[idx], salida, mano.id).map(c => c.p + c.v) : [],
    mesa: sala.mesa,
    turno: sala.turno,
    venceTurno: sala.venceTurno || 0,
    mano: { id: mano.id, nom: mano.nom, ico: mano.ico, tipo: mano.tipo, dueno: mano.dueno },
    iMano: sala.iMano,
    ronda: sala.ronda,
    triunfo: sala.triunfo,
    sinTriunfo: !!sala.sinTriunfo,
    marcador: sala.marcador,
    medallas: sala.medallas || [0,0,0,0],
    puntosMano: sala.puntosMano,
    esperandoTriunfo: sala.esperandoTriunfo,
    ultimaBaza: sala.ultimaBaza,
    terminada: sala.terminada,
    parejas: !!sala.parejas,
    empezoEn: sala.empezoEn || 0,
    rondaEmpezoEn: sala.rondaEmpezoEn || 0,
    duraciones: sala.duraciones || [],
    tiempos: (sala.tiempos || [0,0,0,0]).slice(),
    bazasMano: (sala.bazasMano || [0,0,0,0]).slice(),
    bazasPorMano: (sala.bazasPorMano || []).map(m => ({ id:m.id, dueno:m.dueno, nom:m.nom, bazas:m.bazas.slice() })),
    tiemposRonda: (sala.tiemposRonda || []).map(t => t.slice()),
    acaboEn: sala.acaboEn || 0,
    rondas: sala.rondas
  };
}

/* Si alguien se queda pensando demasiado, se le juega la carta.
   Se elige la más alta del palo de salida; si no puede seguirlo, la más alta que tenga. */
function pararReloj(sala) {
  if (sala.reloj) { clearTimeout(sala.reloj); sala.reloj = null; }
}

function arrancarReloj(sala) {
  pararReloj(sala);
  if (!sala.empezada || sala.terminada) return;
  if ((sala.jugadores[sala.turno] || {}).bot) return;   // los bots juegan solos
  if ((sala.jugadores[sala.turno] || {}).mirando) return;   // está consultando algo
  // Si alguien se ha levantado un momento, nadie pierde su turno
  if (sala.jugadores.some(j => j && j.pausa)) return;
  if ((sala.jugadores[sala.turno] || {}).bot) return;   // los bots ya juegan solos
  if (sala.esperandoTriunfo !== null && sala.esperandoTriunfo !== undefined) return;
  const deQuien = sala.turno;
  sala.venceTurno = Date.now() + ESPERA_TURNO;
  sala.reloj = setTimeout(() => {
    if (!salas.has(sala.codigo) || sala.turno !== deQuien || sala.resolviendo) return;
    const mano = sala.manos[deQuien] || [];
    const salida = sala.mesa.length ? sala.mesa[0].carta.p : null;
    const puede = jugables(mano, salida, MANOS[sala.iMano].id);
    if (!puede.length) return;
    const delPalo = salida ? puede.filter(x => x.p === salida) : [];
    const donde = delPalo.length ? delPalo : puede;
    let alta = donde[0];
    donde.forEach(x => {
      if (VALORES.indexOf(x.v) > VALORES.indexOf(alta.v)) alta = x;
    });
    jugarCarta(sala, deQuien, alta.p + alta.v);
  }, ESPERA_TURNO);
}

/* ═════ BOTS QUE CUBREN LOS PUESTOS QUE FALTEN ═════
   Si una noche no se juntan los cuatro, la mesa sale igual. */
var fuerzaBot = v => VALORES.indexOf(v);

/* Cuánto castiga esta carta en la mano que se juega */
function castigoDe(sala, c){
  var id = MANOS[sala.iMano].id;
  if (id === 'corazones') return c.p === '\u2665' ? 1 : 0;
  if (id === 'jk')        return (c.v === 'J' || c.v === 'K') ? 1 : 0;
  if (id === 'qs')        return c.v === 'Q' ? 1 : 0;
  if (id === 'kh')        return (c.p === '\u2665' && c.v === 'K') ? 1 : 0;
  return 0;
}

/* ¿Queda todavía algún castigo por salir en esta mano?
   Si ya salieron todos, ganar bazas es gratis y conviene soltar lo alto. */
function quedaCastigo(sala){
  var id = MANOS[sala.iMano].id;
  if (id === 'bazas' || id === 'ultimas') return true;   // ahí toda baza cuenta
  var faltan = 0;
  PALOS.forEach(function(p){
    VALORES.forEach(function(v){
      if (sala.salidas[p + v]) return;
      var c = { p:p, v:v };
      if (castigoDe(sala, c) > 0) faltan++;
    });
  });
  // Lo que hay en la mesa ya está contado como salido
  return faltan > 0;
}

/* ¿Queda por salir alguna carta de ese palo más alta que la mía?
   Cuenta lo ya jugado y lo que el propio bot tiene en la mano. */
function mandaLaMia(sala, sitio, carta){
  // Si a los otros tres ya les falta ese palo, no pueden superarla
  var nadieTiene = [0,1,2,3].every(function(s){
    return s === sitio || sala.fallos[s][carta.p];
  });
  if (nadieTiene) return true;

  var mia = sala.manos[sitio];
  for (var i = VALORES.indexOf(carta.v) + 1; i < VALORES.length; i++){
    var clave = carta.p + VALORES[i];
    if (sala.salidas[clave]) continue;                 // ya salió
    var enMiMano = mia.some(function(c){ return c.p === carta.p && c.v === VALORES[i]; });
    if (!enMiMano) return false;                       // alguien la tiene
  }
  return true;
}

/* ¿Alguien puede echarme un castigo si abro por este palo?
   Quien no lo tiene se descarta de lo que quiera, y eso duele. */
function palorPeligroso(sala, sitio, palo){
  return [0,1,2,3].some(function(s){
    return s !== sitio && sala.fallos[s][palo];
  });
}

function elegirBot(sala, sitio){
  var mano   = sala.manos[sitio];
  var salida = sala.mesa.length ? sala.mesa[0].carta.p : null;
  var ops    = jugables(mano, salida, MANOS[sala.iMano].id);
  if (ops.length === 1) return ops[0];



  var esTriunfo = (MANOS[sala.iMano].tipo === 'pos');
  var porFuerza = function(a,b){ return fuerzaBot(a.v) - fuerzaBot(b.v); };

  /* Si en una mano negativa ya salieron todos los castigos, el resto
     de bazas no cuesta nada: se sueltan las cartas altas sin miedo. */
  if (!esTriunfo && !quedaCastigo(sala)){
    return ops.sort(porFuerza)[ops.length - 1];
  }

  /* En las dos últimas, las cartas no castigan: castiga llevarse las bazas 12 y 13.
     Así que hasta la 11 conviene deshacerse de lo alto y guardar lo bajo para el final. */
  if (MANOS[sala.iMano].id === 'ultimas' && sala.nBaza < 12){
    return ops.sort(porFuerza)[ops.length - 1];
  }

  /* ── Abriendo baza ── */
  if (!salida){
    if (esTriunfo){
      /* Con muchos triunfos conviene arrastrarlos: se van los de los rivales
         y después las cartas altas de otros palos ganan solas. */
      if (sala.triunfo){
        var mios = ops.filter(function(c){ return c.p === sala.triunfo; });
        var fueraTri = 0;
        VALORES.forEach(function(v){ if (sala.salidas[sala.triunfo + v]) fueraTri++; });
        var quedanAjenos = 13 - fueraTri - mios.length;
        if (mios.length >= 4 && quedanAjenos > 0){
          // Se arrastra con el más alto para llevarse la baza
          return mios.sort(porFuerza)[mios.length - 1];
        }
      }
      // Interesa llevarse bazas: se abre con lo que nadie puede superar
      var seguras = ops.filter(function(c){ return mandaLaMia(sala, sitio, c); });
      if (seguras.length){
        // Primero las que no son triunfo, para guardarlo
        var fuera = seguras.filter(function(c){ return c.p !== sala.triunfo; });
        var lista = fuera.length ? fuera : seguras;
        return lista.sort(porFuerza)[lista.length - 1];
      }
      /* Si ninguna manda, abrir alto es regalar la carta: te la comen con
         la que aún está fuera. Se sale bajo y se guardan las altas para
         ganar cuando abra otro. El triunfo también se reserva. */
      var noTri = ops.filter(function(c){ return c.p !== sala.triunfo; });
      var donde = noTri.length ? noTri : ops;
      return donde.sort(porFuerza)[0];
    }
    /* En las negativas, abrir es peligroso: si tu carta manda te comes la baza.
       Nunca se abre con una carta que castiga (J, K, dama, corazón, según la mano)
       ni con una que ya no puede superar nadie. Se sale bajo y por un palo
       donde todavía haya cartas altas fuera. */
    /* En parejas conviene abrir por donde el compañero manda: si él se lleva
       la baza, el castigo se lo queda el equipo igual, pero al menos no
       se lo comen los rivales por sorpresa. Se evita el palo que él ya no tiene. */
    if (sala.parejas){
      var compa = (sitio + 2) % 4;
      var buenas = ops.filter(function(c){
        return castigoDe(sala, c) === 0 && !sala.fallos[compa][c.p];
      });
      if (buenas.length) return buenas.sort(porFuerza)[0];
    }

    var limpias = ops.filter(function(c){
      return castigoDe(sala, c) === 0 && !mandaLaMia(sala, sitio, c);
    });
    // Mejor aún si nadie se ha quedado sin ese palo: no podrán descargarte nada
    var seguras = limpias.filter(function(c){ return !palorPeligroso(sala, sitio, c.p); });

    /* Entre varias salidas buenas, la mejor es la del palo donde mi carta más
       alta sea la más baja: ese palo lo puedo soltar entero sin acabar
       comiéndome una baza más adelante. Salir por donde guardo un as es
       aplazar el problema. */
    function riesgoDelPalo(palo){
      var alta = -1;
      sala.manos[sitio].forEach(function(c){
        if (c.p === palo && fuerzaBot(c.v) > alta) alta = fuerzaBot(c.v);
      });
      return alta;
    }
    function mejorSalida(lista){
      return lista.slice().sort(function(a,b){
        return (riesgoDelPalo(a.p) - riesgoDelPalo(b.p)) || (fuerzaBot(a.v) - fuerzaBot(b.v));
      })[0];
    }
    if (seguras.length) return mejorSalida(seguras);
    if (limpias.length) return mejorSalida(limpias);

    // Si todo lo que queda castiga o manda, al menos que no mande
    var noMandan = ops.filter(function(c){ return !mandaLaMia(sala, sitio, c); });
    if (noMandan.length){
      return noMandan.sort(function(a,b){
        return (castigoDe(sala, a) - castigoDe(sala, b)) || (fuerzaBot(a.v) - fuerzaBot(b.v));
      })[0];
    }
    // Sin salida: la más baja y que castigue lo menos posible
    return ops.sort(function(a,b){
      return (castigoDe(sala, a) - castigoDe(sala, b)) || (fuerzaBot(a.v) - fuerzaBot(b.v));
    })[0];
  }

  /* ── Respondiendo ── */
  function gana(c){
    return ganadorBaza(sala.mesa.concat([{ jugador:'x', carta:c }]), sala.triunfo) === 'x';
  }

  /* En parejas, lo que gana el compañero lo gana tu equipo:
     ni se le arrebata la baza ni se le carga un castigo. */
  if (sala.parejas && sala.mesa.length &&
      ganadorBaza(sala.mesa, sala.triunfo) === (sitio + 2) % 4){
    if (esTriunfo) return ops.sort(porFuerza)[0];
    var sinDanyo = ops.filter(function(c){ return castigoDe(sala, c) === 0; });
    var dondeD = sinDanyo.length ? sinDanyo : ops;
    return dondeD.sort(function(a,b){
      return (castigoDe(sala, a) - castigoDe(sala, b)) || (fuerzaBot(a.v) - fuerzaBot(b.v));
    })[0];
  }
  if (esTriunfo){
    var ganadoras = ops.filter(gana);
    if (ganadoras.length) return ganadoras.sort(porFuerza)[0];   // la justa
    return ops.sort(porFuerza)[0];                                // se descarta bajo
  }
  /* En Corazones, JK, Qs y K♥ la baza solo cuesta si lleva castigo dentro.
     Siendo el último en jugar ya se sabe: si viene limpia, ganarla sale
     gratis y conviene aprovechar para soltar la carta más alta. */
  var idMano = MANOS[sala.iMano].id;
  if (idMano !== 'bazas' && sala.mesa.length === 3){
    var castigoEnMesa = 0;
    sala.mesa.forEach(function(x){ castigoEnMesa += castigoDe(sala, x.carta); });
    if (castigoEnMesa === 0){
      var sinCoste = ops.filter(function(c){ return castigoDe(sala, c) === 0; });
      if (sinCoste.length) return sinCoste.sort(porFuerza)[sinCoste.length - 1];
    }
  }

  var libres = ops.filter(function(c){ return !gana(c); });
  if (libres.length){
    // Sin riesgo: se aprovecha para soltar lo que más castiga
    return libres.sort(function(a,b){
      return (castigoDe(sala, b) - castigoDe(sala, a)) || (fuerzaBot(b.v) - fuerzaBot(a.v));
    })[0];
  }
  // Toca cargar: lo menos malo
  return ops.sort(function(a,b){
    return (castigoDe(sala, a) - castigoDe(sala, b)) || (fuerzaBot(a.v) - fuerzaBot(b.v));
  })[0];
}

/* El triunfo no es solo el palo más largo: cuatro pequeñas valen menos
   que tres con as y rey. Se cuenta la longitud y además la fuerza. */
function triunfoBot(sala, sitio){
  var valor = {};
  PALOS.forEach(function(p){ valor[p] = 0; });
  sala.manos[sitio].forEach(function(c){
    // Cada carta suma por estar, y las altas suman bastante más
    valor[c.p] += 2 + Math.max(0, fuerzaBot(c.v) - 7);
  });
  var mejor = PALOS[0];
  PALOS.forEach(function(p){ if (valor[p] > valor[mejor]) mejor = p; });
  return mejor;
}

/* Al bot le toca: juega tras una pausa para que se siga la jugada */
function turnoDeLosBots(sala) {
  if (sala.penso) { clearTimeout(sala.penso); sala.penso = null; }
  if (!sala.empezada || sala.terminada || sala.resolviendo) return;
  if (sala.jugadores.some(j => j && j.pausa)) return;

  const et = sala.esperandoTriunfo;
  if (et !== null && et !== undefined) {
    if (!(sala.jugadores[et] || {}).bot) return;
    sala.penso = setTimeout(() => {
      if (!salas.has(sala.codigo) || sala.esperandoTriunfo !== et) return;
      sala.triunfo = triunfoBot(sala, et);
      sala.sinTriunfo = false;
      sala.esperandoTriunfo = null;
      sala.turno = quienAbre(sala);
      sincronizar(sala);
    }, 1200);
    return;
  }

  const q = sala.turno;
  if (!(sala.jugadores[q] || {}).bot) return;
  const espera = sala.mesa.length === 0 ? 400 : (700 + Math.random() * 400);
  sala.penso = setTimeout(() => {
    if (!salas.has(sala.codigo) || sala.turno !== q || sala.resolviendo) return;
    const carta = elegirBot(sala, q);
    if (carta) jugarCarta(sala, q, carta.p + carta.v);
  }, espera);
}

function sincronizar(sala) {
  // Cada vez que cambia el estado se reajusta el reloj del turno
  if (sala.empezada && !sala.terminada &&
      (sala.esperandoTriunfo === null || sala.esperandoTriunfo === undefined)) {
    arrancarReloj(sala);
  } else {
    pararReloj(sala);
  }
  sala.jugadores.forEach((j, i) => enviar(j.ws, 'estado', { estado: estadoPara(sala, i) }));
  turnoDeLosBots(sala);
}

/* Si el turno cae en un asiento que alguien dejó libre, se avisa a la mesa
   para que no parezca que el juego se ha colgado. */
function avisarSiVacante(sala) {
  const j = sala.jugadores[sala.turno];
  if (j && j.vacante) {
    difundir(sala, 'esperandoJugador', { sitio: sala.turno, nombre: j.nombre });
  }
}

/* ─────────── FLUJO DE LA PARTIDA ─────────── */
function arrancarMano(sala) {
  sala.manos = repartir();
  sala.mesa = [];
  sala.nBaza = 1;
  sala.triunfo = null;
  sala.sinTriunfo = false;
  sala.salidas = {};
  sala.fallos = [{},{},{},{}];
  sala.puntosMano = [0,0,0,0];
  sala.bazasMano = [0,0,0,0];   // las de la mano que empieza
  sala.ultimaBaza = null;
  sala.resolviendo = false;
  const mano = MANOS[sala.iMano];
  if (mano.tipo === 'pos') {
    // El dueño de la mano elige el palo antes de empezar
    sala.esperandoTriunfo = mano.dueno;
  } else {
    sala.esperandoTriunfo = null;
    sala.turno = quienAbre(sala);
  }
  sincronizar(sala);
  avisarSiVacante(sala);
}

function jugarCarta(sala, idx, texto) {
  if (!sala.empezada || sala.terminada) return;
  if (sala.esperandoTriunfo !== null) return;
  // Mientras la baza se resuelve nadie puede adelantarse
  if (sala.resolviendo) return;
  if (sala.turno !== idx) return;
  // Una carta por jugador en cada baza
  if (sala.mesa.some(x => x.jugador === idx)) return;
  const mano = MANOS[sala.iMano];
  const salida = sala.mesa.length ? sala.mesa[0].carta.p : null;
  const permitidas = jugables(sala.manos[idx], salida, mano.id);
  const carta = permitidas.find(c => c.p + c.v === texto);
  if (!carta) return;   // jugada no válida: se ignora

  // Lo que ha tardado en decidirse, para saber quién va más lento
  sala.tiempos = sala.tiempos || [0,0,0,0];
  if (sala.turnoDesde) sala.tiempos[idx] += Date.now() - sala.turnoDesde;
  sala.turnoDesde = Date.now();

  const i = sala.manos[idx].findIndex(c => c.p === carta.p && c.v === carta.v);
  sala.manos[idx].splice(i, 1);
  if (sala.jugadores[idx]) sala.jugadores[idx].mirando = false;
  sala.mesa.push({ jugador: idx, carta });
  sala.salidas[carta.p + carta.v] = true;
  if (salida && carta.p !== salida) sala.fallos[idx][salida] = true;

  if (sala.mesa.length < 4) {
    sala.turno = (sala.turno + 1) % 4;
    sincronizar(sala);
    avisarSiVacante(sala);
    return;
  }

  // Baza completa: se resuelve y se deja ver un momento
  sala.resolviendo = true;
  const g = ganadorBaza(sala.mesa, sala.triunfo);
  const pts = puntosBaza(mano.id, sala.mesa, sala.nBaza);
  // En parejas, lo que gana uno lo apunta también su compañero
  if (sala.parejas) {
    const compa = (g + 2) % 4;
    sala.puntosMano[g] += pts;
    sala.puntosMano[compa] = sala.puntosMano[g];
  } else {
    sala.puntosMano[g] += pts;
  }
  if (MANOS[sala.iMano].id === 'kh' &&
      sala.mesa.some(x => x.carta.p === '\u2665' && x.carta.v === 'K')) {
    sala.reyesCargados = sala.reyesCargados || [0,0,0,0];
    sala.reyesCargados[g]++;
  }
  // Cuántas bazas se ha llevado cada uno en la ronda
  sala.bazasMano = sala.bazasMano || [0,0,0,0];
  sala.bazasMano[g] += castigosBaza(MANOS[sala.iMano].id, sala.mesa, sala.nBaza);
  sala.ultimaBaza = { cartas: sala.mesa.slice(), ganador: g, puntos: pts, baza: sala.nBaza };
  sincronizar(sala);

  setTimeout(() => {
    sala.mesa = [];
    sala.resolviendo = false;
    sala.nBaza++;
    sala.turno = g;
    const seAcabo = sala.nBaza > 13 || !quedanCastigos(sala);
    if (seAcabo) terminarMano(sala);
    else sincronizar(sala);
  }, PAUSA_BAZA);
}

function terminarMano(sala) {
  for (let j = 0; j < 4; j++) sala.marcador[j] += sala.puntosMano[j];
  // Cuántas bazas se llevó cada uno en esta mano
  sala.bazasPorMano = sala.bazasPorMano || [];
  sala.bazasPorMano.push({ id: MANOS[sala.iMano].id, dueno: MANOS[sala.iMano].dueno,
                           nom: MANOS[sala.iMano].nom,
                           bazas: (sala.bazasMano || [0,0,0,0]).slice() });
  difundir(sala, 'finMano', { puntos: sala.puntosMano.slice(), marcador: sala.marcador.slice() });

  setTimeout(() => {
    if (sala.iMano >= MANOS.length - 1) {
      // Se guarda cómo quedó cada uno en esta ronda
      const puntos = sala.marcador.slice();
      const orden = [0,1,2,3].slice().sort((a,b) => puntos[b] - puntos[a]);
      const puesto = [0,0,0,0];
      orden.forEach((s,i) => { puesto[s] = i + 1; });
      // Medalla para quien gane la ronda; en parejas, para los dos
      sala.medallas = sala.medallas || [0,0,0,0];
      const mejor = (sala.parejas ? [0,1] : [0,1,2,3])
        .slice().sort((a,b) => puntos[b] - puntos[a])[0];
      // El reloj de la ronda se detiene y su tiempo se guarda
      sala.duraciones = sala.duraciones || [];
      sala.duraciones.push(Date.now() - (sala.rondaEmpezoEn || Date.now()));
      // Lo que tardó cada uno en esta ronda
      sala.tiemposRonda = sala.tiemposRonda || [];
      sala.tiemposRonda.push((sala.tiempos || [0,0,0,0]).slice());
      sala.medallas[mejor]++;
      if (sala.parejas) sala.medallas[(mejor + 2) % 4]++;
      sala.rondas.push({ ronda: sala.ronda, puesto: puesto, puntos: puntos,
                         bazas: (sala.bazasPorMano || []).map(m => ({ id:m.id, dueno:m.dueno, nom:m.nom, bazas:m.bazas.slice() })) });
      if (sala.ronda >= RONDAS_PARTIDA){
        sala.terminada = true;
        sala.acaboEn = Date.now();
        // El total de la partida es la suma de las cuatro rondas
        const totales = [0,0,0,0];
        sala.rondas.forEach(r => { for (let s = 0; s < 4; s++) totales[s] += r.puntos[s]; });
        apuntarPartida(sala, totales);
        sincronizar(sala);   // que los cuatro sepan que se acabó
        difundir(sala, 'finPartida', { marcador: totales, rondas: sala.rondas });
        return;   // no se reparte más
      }
      difundir(sala, 'finRonda', { marcador: puntos,
                                   duracion: (sala.duraciones || []).slice(-1)[0] || 0,
                                   tiempos: ((sala.tiemposRonda || []).slice(-1)[0] || [0,0,0,0]).slice() });
      sala.ronda++;
      sala.rondaEmpezoEn = Date.now();   // el reloj arranca de cero
      sala.bazasPorMano = [];
      sala.bazasPorMano = [];
      sala.tiempos = [0,0,0,0];
      sala.turnoDesde = Date.now();
      // El orden de salida no rota: cada ronda repite la misma secuencia
      sala.iMano = 0;
      sala.marcador = [0,0,0,0];   // la ronda nueva arranca de cero
        } else {
      sala.iMano++;
    }
    arrancarMano(sala);
  }, PAUSA_MANO);
}

/* ─────────── CONEXIONES ─────────── */
wss.on('connection', ws => {
  let sala = null, idx = -1;

  ws.on('message', async bruto => {
    let m;
    try { m = JSON.parse(bruto); } catch (e) { return; }

    /* Crear una mesa nueva */
    if (m.tipo === 'crear') {
      if (!(await dejaPasar(ws, m))) return;
      const codigo = codigoNuevo();
      sala = crearSala(codigo);
      // Cuatro dígitos al azar: sin esto cualquiera que sepa la dirección se sentaría
      salas.set(codigo, sala);
      idx = 0;
      sala.jugadores.push({ id: m.id, nombre: (m.nombre || 'Jugador').slice(0, 12), ws, conectado: true,
                            color: colorLibre(sala, m.color) });
      enviar(ws, 'sala', { codigo, yo: idx });
      sincronizar(sala);
      return;
    }

    /* Cambiar de color desde la sala de espera */
    if (m.tipo === 'color') {
      if (!sala || idx < 0) return;
      if (sala.empezada) return;                      // ya no, la partida va
      const libre = colorLibre(sala, m.color);
      if (libre !== m.color) return;                  // lo pidió ocupado: se ignora
      sala.jugadores[idx].color = libre;
      sincronizar(sala);
      return;
    }

    /* Entrar a una mesa existente */
    if (m.tipo === 'entrar') {
      if (!(await dejaPasar(ws, m))) return;
      const cod = (m.codigo || '').toUpperCase().trim();
      const s = salas.get(cod);
      if (!s) { enviar(ws, 'error', { texto: 'No existe ninguna mesa con ese código' }); return; }

      // Si vuelve alguien que ya estaba, recupera su sitio
      const previo = s.jugadores.findIndex(j => j.id === m.id);
      if (previo >= 0) {
        sala = s; idx = previo;
        s.jugadores[previo].ws = ws;
        s.jugadores[previo].conectado = true;
        enviar(ws, 'sala', { codigo: cod, yo: idx });
        sincronizar(s);
        return;
      }

      // ¿Hay un asiento libre porque alguien se marchó?
      const vacante = s.jugadores.findIndex(j => j.vacante);
      if (vacante >= 0) {
        sala = s; idx = vacante;
        s.jugadores[vacante] = { id: m.id, nombre: (m.nombre || 'Jugador').slice(0,12),
                                 ws, conectado: true,
                                 color: colorLibre(s, m.color) };   // deja de llevarlo el bot
        enviar(ws, 'sala', { codigo: cod, yo: idx });
        sincronizar(s);
        return;
      }
      if (s.jugadores.length >= 4) { enviar(ws, 'error', { texto: 'La mesa ya está completa' }); return; }
      sala = s;
      idx = s.jugadores.length;
      s.jugadores.push({ id: m.id, nombre: (m.nombre || 'Jugador').slice(0, 12), ws, conectado: true, color: colorLibre(s, m.color) });
      enviar(ws, 'sala', { codigo: cod, yo: idx });
      sincronizar(s);
      return;
    }

    if (!sala) return;

    /* El anfitrión da comienzo cuando están los cuatro */
    /* El anfitrión elige si se juega en parejas */
    if (m.tipo === 'modo' && idx === 0 && !sala.empezada) {
      sala.parejas = !!m.parejas;
      sincronizar(sala);
      return;
    }

    if (m.tipo === 'empezar' && idx === 0 && !sala.empezada) {
      if (sala.jugadores.length < 2) return;   // al menos alguien más que tú, o un bot
      // Los puestos que falten los cubren los bots
      const NOMBRES_BOT = ['Ali', 'Dianis', 'Fede'];
      let n = 0;
      while (sala.jugadores.length < 4) {
        sala.jugadores.push({ id: null, nombre: NOMBRES_BOT[n++] || ('Bot ' + n),
                              ws: null, conectado: true, bot: true });
      }
      sala.empezada = true;
      sala.empezoEn = Date.now();
      sala.rondaEmpezoEn = Date.now();
      sala.duraciones = [];
      sala.tiempos = [0,0,0,0];
      sala.tiemposRonda = [];
      sala.turnoDesde = Date.now();
      sala.bazasPorMano = [];
      arrancarMano(sala);
      return;
    }

    /* Rellenar la mesa con bots sin esperar a nadie más */
    if (m.tipo === 'conBots' && idx === 0 && !sala.empezada) {
      const NOMBRES_BOT = ['Ali', 'Dianis', 'Fede'];
      let n = 0;
      while (sala.jugadores.length < 4) {
        sala.jugadores.push({ id: null, nombre: NOMBRES_BOT[n++] || ('Bot ' + n),
                              ws: null, conectado: true, bot: true });
      }
      sala.empezada = true;
      arrancarMano(sala);
      return;
    }

    /* Elegir el palo de triunfo */
    if (m.tipo === 'triunfo' && sala.esperandoTriunfo === idx) {
      const estrella = (m.palo === '\u2605');
      if (!estrella && !PALOS.includes(m.palo)) return;
      sala.triunfo = estrella ? null : m.palo;
      sala.sinTriunfo = estrella;   // la estrella: manda solo el palo de salida
      sala.esperandoTriunfo = null;
      sala.turno = quienAbre(sala);
      sincronizar(sala);
      return;
    }

    /* Jugar una carta */
    if (m.tipo === 'jugar') {
      jugarCarta(sala, idx, m.carta);
      return;
    }

    /* Mirando una pantalla: el reloj espera, como si fuera una pausa breve */
    if (m.tipo === 'mirando') {
      const j = sala.jugadores[idx];
      if (!j || j.bot) return;
      j.mirando = !!m.abierto;
      if (sala.turno === idx) { if (j.mirando) pararReloj(sala); else arrancarReloj(sala); }
      return;
    }

    /* Vuelvo enseguida: se para el reloj para que no se juegue solo */
    if (m.tipo === 'pausa') {
      const j = sala.jugadores[idx];
      if (!j || j.bot) return;   // un bot no se levanta de la mesa
      j.pausa = !!m.activa;
      j.desdePausa = j.pausa ? Date.now() : 0;
      sincronizar(sala);
      return;
    }

    /* Sacar a alguien de la mesa: solo el anfitrión */
    if (m.tipo === 'expulsar' && idx === 0) {
      const s = parseInt(m.sitio, 10);
      if (!(s >= 1 && s <= 3) || !sala.jugadores[s]) return;
      const fuera = sala.jugadores[s];
      if (fuera.ws) { try { enviar(fuera.ws, 'error', { texto: 'El anfitrión te sacó de la mesa' }); } catch(e){} }
      if (!sala.empezada) sala.jugadores.splice(s, 1);
      else sala.jugadores[s] = { id: null, nombre: fuera.nombre, ws: null,
                                 conectado: false, vacante: true, bot: true };
      sincronizar(sala);
      return;
    }

    /* Dejar la mesa: el sitio queda libre para otro */
    if (m.tipo === 'salir') {
      const nombre = sala.jugadores[idx] ? sala.jugadores[idx].nombre : '?';
      if (!sala.empezada) {
        sala.jugadores.splice(idx, 1);
      } else {
        // En partida, el asiento queda vacante y puede ocuparlo alguien
        // Un bot le sustituye para que la partida no se detenga,
        // y el asiento sigue libre por si vuelve o entra otro
        sala.jugadores[idx] = { id: null, nombre: nombre, ws: null,
                                conectado: false, vacante: true, bot: true };
      }
      if (!sala.jugadores.some(j => j.ws)) { salas.delete(sala.codigo); sala = null; idx = -1; return; }
      pasarElMando(sala);
      sincronizar(sala);
      if (sala.empezada && !sala.terminada) avisarSiVacante(sala);
      sala = null; idx = -1;
      return;
    }

    /* Empezar otra partida con los mismos jugadores */
    if (m.tipo === 'revancha' && idx === 0 && sala.terminada) {
      sala.terminada = false;
      sala.ronda = 1;
      sala.iMano = 0;
      sala.abreBase = 3;
      sala.marcador = [0,0,0,0];
      sala.rondas = [];
      sala.reyesCargados = [0,0,0,0];
      sala.medallas = [0,0,0,0];
      sala.empezoEn = Date.now();
      sala.rondaEmpezoEn = Date.now();
      sala.duraciones = [];
      sala.tiempos = [0,0,0,0];
      sala.tiemposRonda = [];
      sala.turnoDesde = Date.now();
      sala.bazasPorMano = [];
      sala.acaboEn = 0;
          arrancarMano(sala);
      return;
    }

  });

  ws.on('close', () => {
    if (!sala || idx < 0) return;
    if (sala.jugadores[idx]) sala.jugadores[idx].conectado = false;
    // Antes de empezar, el sitio queda libre para otro
    if (!sala.empezada) {
      sala.jugadores.splice(idx, 1);
      if (!sala.jugadores.length) { salas.delete(sala.codigo); return; }
    }
    pasarElMando(sala);
    sincronizar(sala);
  });
});

/* Las mesas abandonadas se recogen cada media hora */
setInterval(() => {
  salas.forEach((s, cod) => {
    if (!s.jugadores.some(j => j.conectado)) salas.delete(cod);
  });
}, 30 * 60 * 1000);

